//! Viewport parity (ex-505).
//!
//! `tests/fixtures/viewport.json` is upstream's own viewport code at the
//! pinned commit, generated by `tools/goldens/viewport.mjs`:
//! `getNormalizedZoom` (`scene/normalize.ts`), the coordinate transforms
//! (`packages/common/src/utils.ts:317-358`), `constrainScrollState`,
//! `getViewportForZoomWithScrollConstraints`, `zoomToFitBounds`,
//! `centerScrollOn`, `scrollBoundsIntoView`, `getClosestElementBounds` and
//! `getScrollToContentState` (`packages/excalidraw/viewport.ts`),
//! `AppViewport.translate` and `AppViewport.setViewport` step by step
//! with its animation frames (`components/App.viewport.ts`), `AppWheel.handle`
//! (`components/App.wheel.ts`) event by event, and the zoom actions of
//! `actions/actionCanvas.tsx` (perform and keyTest). Every case is
//! reproduced exactly (same doubles).
//!
//! The tests after the replay port the assertions of upstream's
//! `tests/wheel.test.tsx`, `tests/scrollConstraints.test.tsx` (pure
//! suites), `tests/viewport.test.ts` and `tests/fitToContent.test.tsx`
//! one by one, and pin the constants and the wheel formula
//! (`site/content/research/rendering.md` section 4).

use excali_core::app_state::AppState;
use excali_core::constants::{MAX_ZOOM, MIN_ZOOM, ZOOM_STEP};
use excali_core::element::Element;
use excali_editor::viewport::{
    center_scroll_on, constrain_scroll_state, ease_out, get_closest_element_bounds,
    get_normalized_zoom, get_scroll_to_content_state,
    get_viewport_for_zoom_with_scroll_constraints, handle_wheel, perform_zoom_action,
    scene_coords_to_viewport_coords, scroll_bounds_into_view, translate,
    viewport_coords_to_scene_coords, wheel_zoom_value, zoom_to_fit_bounds, AppViewport, Fit,
    InputDevice, Offsets, Overscroll, ScrollConstraints, SetViewportOptions, TooLarge,
    TranslateOptions, Viewport, ViewportAnimation, ViewportLock, ViewportState, ViewportUpdate,
    WheelContext, WheelEvent, WheelOutcome, WheelTarget, ZoomAction, ZoomKeyEvent, ZoomToFit,
    DEFAULT_OVERSCROLL,
};
use excali_math::js;
use serde_json::{json, Map, Value};

const FIXTURE: &str = include_str!("fixtures/viewport.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("viewport.json parses")
}

/// A fixture number: a JSON number, or "NaN" / "Infinity" / "-Infinity".
fn num(v: &Value) -> f64 {
    match v {
        Value::Number(n) => n.as_f64().expect("a double"),
        Value::String(s) => match s.as_str() {
            "NaN" => f64::NAN,
            "Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            other => panic!("not a number: {other}"),
        },
        other => panic!("not a number: {other}"),
    }
}

fn opt_num(v: &Value, key: &str) -> Option<f64> {
    v.get(key).filter(|x| !x.is_null()).map(num)
}

/// Same double, NaN included; `-0` and `0` are equal (JSON writes both 0).
fn same(a: f64, b: f64) -> bool {
    (a.is_nan() && b.is_nan()) || a == b
}

fn assert_same(actual: f64, expected: f64, what: &str) {
    assert!(
        same(actual, expected),
        "{what}: got {actual:?}, upstream {expected:?}"
    );
}

fn assert_viewport(actual: Viewport, expected: &Value, what: &str) {
    assert_same(
        actual.scroll_x,
        num(&expected["scrollX"]),
        &format!("{what} scrollX"),
    );
    assert_same(
        actual.scroll_y,
        num(&expected["scrollY"]),
        &format!("{what} scrollY"),
    );
    assert_same(actual.zoom, num(&expected["zoom"]), &format!("{what} zoom"));
}

fn offsets(v: Option<&Value>) -> Offsets {
    v.filter(|v| !v.is_null())
        .map(Offsets::from_json)
        .unwrap_or_default()
}

/// A fixture state (`zoom` as a number, the rest as upstream names them).
fn state(v: &Value) -> ViewportState {
    ViewportState {
        scroll_x: opt_num(v, "scrollX").unwrap_or(0.0),
        scroll_y: opt_num(v, "scrollY").unwrap_or(0.0),
        zoom: num(&v["zoom"]),
        width: opt_num(v, "width").unwrap_or(0.0),
        height: opt_num(v, "height").unwrap_or(0.0),
        offset_left: opt_num(v, "offsetLeft").unwrap_or(0.0),
        offset_top: opt_num(v, "offsetTop").unwrap_or(0.0),
        scroll_constraints: v
            .get("scrollConstraints")
            .and_then(ScrollConstraints::from_json),
    }
}

fn bounds(v: &Value) -> [f64; 4] {
    let a = v.as_array().expect("bounds");
    [num(&a[0]), num(&a[1]), num(&a[2]), num(&a[3])]
}

fn elements(f: &Value) -> Vec<Element> {
    f["elements"]
        .as_array()
        .expect("elements")
        .iter()
        .map(|e| {
            Element::from_map(e.as_object().expect("an element").clone())
                .expect("an element upstream built")
        })
        .collect()
}

fn element_set<'a>(f: &Value, all: &'a [Element], set: &str) -> Vec<&'a Element> {
    let ids: Vec<&str> = f["elementSets"][set]
        .as_array()
        .unwrap_or_else(|| panic!("no element set {set}"))
        .iter()
        .map(|id| id.as_str().expect("an id"))
        .collect();
    all.iter()
        .filter(|e| ids.contains(&e.base.id.as_str()))
        .collect()
}

// -- constants and the zoom formula ---------------------------------------------

#[test]
fn zoom_limits_and_step_are_upstreams() {
    // constants.ts:362-364, viewport.ts:41
    assert_eq!(MIN_ZOOM, 0.1);
    assert_eq!(MAX_ZOOM, 30.0);
    assert_eq!(ZOOM_STEP, 0.1);
    assert_eq!(DEFAULT_OVERSCROLL, 150.0);
    let c = &fixture()["constants"];
    assert_eq!(num(&c["MIN_ZOOM"]), MIN_ZOOM);
    assert_eq!(num(&c["MAX_ZOOM"]), MAX_ZOOM);
    assert_eq!(num(&c["ZOOM_STEP"]), ZOOM_STEP);
    assert_eq!(num(&c["DEFAULT_OVERSCROLL"]), DEFAULT_OVERSCROLL);
}

#[test]
fn normalized_zoom_matches_upstream() {
    let f = fixture();
    let cases = f["normalizedZoom"].as_array().expect("cases");
    assert!(cases.len() >= 30);
    for c in cases {
        let input = num(&c["input"]);
        assert_same(
            get_normalized_zoom(input),
            num(&c["output"]),
            &format!("getNormalizedZoom({input:?})"),
        );
    }
}

#[test]
fn normalized_zoom_rounds_to_six_places_then_clamps() {
    // clamp(round(zoom, 6), MIN_ZOOM, MAX_ZOOM)
    assert_eq!(get_normalized_zoom(1.23456749), 1.234567);
    assert_eq!(get_normalized_zoom(1.2345675), 1.234568);
    assert_eq!(get_normalized_zoom(0.05), MIN_ZOOM);
    assert_eq!(get_normalized_zoom(-1.0), MIN_ZOOM);
    assert_eq!(get_normalized_zoom(31.0), MAX_ZOOM);
    assert_eq!(get_normalized_zoom(f64::INFINITY), MAX_ZOOM);
    assert_eq!(get_normalized_zoom(f64::NEG_INFINITY), MIN_ZOOM);
    assert!(get_normalized_zoom(f64::NAN).is_nan());
}

#[test]
fn wheel_formula() {
    // App.wheel.ts zoomBy: newZoom = z - delta/100
    //   + log10(max(1, z)) * -sign(Δ) * min(1, |Δ|/20), delta capped at
    //   ZOOM_STEP * 100, then getNormalizedZoom(max(newZoom, minZoom))
    let step = |z: f64, d: f64| wheel_zoom_value(z, d, MIN_ZOOM);
    // below 100% only the linear term: one notch of 100 is capped at 10
    assert_eq!(step(1.0, -100.0), 1.1);
    assert_eq!(step(0.5, 100.0), 0.4);
    assert_eq!(step(0.5, -4.0), 0.54);
    // above 100% the steps grow by log10(z), scaled by min(1, |Δ|/20)
    let expected = get_normalized_zoom(1.1 - 0.1 - js::log10(1.1));
    assert_eq!(step(1.1, 100.0), expected);
    assert_eq!(step(1.1, 100.0), 0.958607);
    let z = 5.0;
    let expected = get_normalized_zoom(z + 0.05 + js::log10(5.0) * (5.0 / 20.0));
    assert_eq!(step(z, -5.0), expected);
    // the limits
    assert_eq!(step(0.1, 100.0), MIN_ZOOM);
    assert_eq!(step(30.0, -100.0), MAX_ZOOM);
    // a zoom lock floors the zoom-out
    assert_eq!(wheel_zoom_value(0.6, 100.0, 0.5), 0.5);
}

// -- coordinate transforms ------------------------------------------------------

#[test]
fn coordinate_transforms_match_upstream() {
    let f = fixture();
    for c in f["coords"].as_array().expect("coords") {
        let s = state(&c["state"]);
        let [x, y] = [num(&c["point"][0]), num(&c["point"][1])];
        let (sx, sy) = viewport_coords_to_scene_coords(x, y, &s);
        assert_same(sx, num(&c["toScene"]["x"]), "toScene x");
        assert_same(sy, num(&c["toScene"]["y"]), "toScene y");
        let (vx, vy) = scene_coords_to_viewport_coords(x, y, &s);
        assert_same(vx, num(&c["toViewport"]["x"]), "toViewport x");
        assert_same(vy, num(&c["toViewport"]["y"]), "toViewport y");
    }
}

#[test]
fn coordinate_transforms_invert_each_other() {
    let s = ViewportState {
        scroll_x: 12.5,
        scroll_y: -7.25,
        zoom: 2.0,
        width: 1000.0,
        height: 800.0,
        offset_left: 10.0,
        offset_top: 20.0,
        scroll_constraints: None,
    };
    let (sx, sy) = viewport_coords_to_scene_coords(110.0, 220.0, &s);
    // (110 - 10) / 2 - 12.5, (220 - 20) / 2 + 7.25
    assert_eq!((sx, sy), (37.5, 107.25));
    assert_eq!(scene_coords_to_viewport_coords(sx, sy, &s), (110.0, 220.0));
}

