#[test]
fn constrain_scroll_state_matches_upstream() {
    let f = fixture();
    for c in f["constrain"].as_array().expect("constrain") {
        let name = c["name"].as_str().unwrap();
        let overscroll = opt_num(c, "overscroll").unwrap_or(0.0);
        assert_viewport(
            constrain_scroll_state(&state(&c["state"]), overscroll),
            &c["result"],
            name,
        );
    }
}

fn locked(x: f64, y: f64, w: f64, h: f64) -> ScrollConstraints {
    ScrollConstraints {
        x,
        y,
        width: w,
        height: h,
        lock_scroll: false,
        lock_zoom: false,
        zoom: 1.0,
        overscroll: 0.0,
        offsets: Offsets::default(),
    }
}

fn view_200x100(
    scroll_x: f64,
    scroll_y: f64,
    zoom: f64,
    lock: Option<ScrollConstraints>,
) -> ViewportState {
    ViewportState {
        scroll_x,
        scroll_y,
        zoom,
        width: 200.0,
        height: 100.0,
        offset_left: 0.0,
        offset_top: 0.0,
        scroll_constraints: lock,
    }
}

#[test]
fn upstream_scroll_lock_suites() {
    // scrollConstraints.test.tsx "constrainScrollState (pure)"
    let no_lock = constrain_scroll_state(&view_200x100(123.0, -45.0, 0.5, None), 0.0);
    assert_eq!(
        no_lock,
        Viewport {
            scroll_x: 123.0,
            scroll_y: -45.0,
            zoom: 0.5
        }
    );

    let zoom_only = ScrollConstraints {
        lock_zoom: true,
        zoom: 0.2,
        ..locked(0.0, 0.0, 1000.0, 1000.0)
    };
    let r = constrain_scroll_state(&view_200x100(9999.0, 9999.0, 1.0, Some(zoom_only)), 0.0);
    assert_eq!((r.scroll_x, r.scroll_y), (9999.0, 9999.0));

    let scroll_lock = ScrollConstraints {
        lock_scroll: true,
        ..locked(0.0, 0.0, 1000.0, 1000.0)
    };
    let r = constrain_scroll_state(
        &view_200x100(0.0, 0.0, 0.15, Some(scroll_lock.clone())),
        0.0,
    );
    assert!((r.zoom - 0.15).abs() < 1e-9);
    let corner = constrain_scroll_state(
        &view_200x100(100.0, 100.0, 1.0, Some(scroll_lock.clone())),
        0.0,
    );
    assert_eq!((corner.scroll_x, corner.scroll_y), (0.0, 0.0));
    let far = constrain_scroll_state(
        &view_200x100(-5000.0, -5000.0, 1.0, Some(scroll_lock.clone())),
        0.0,
    );
    assert_eq!((far.scroll_x, far.scroll_y), (-800.0, -900.0));
    let inside = constrain_scroll_state(
        &view_200x100(-100.0, -100.0, 1.0, Some(scroll_lock.clone())),
        0.0,
    );
    assert_eq!(
        inside,
        Viewport {
            scroll_x: -100.0,
            scroll_y: -100.0,
            zoom: 1.0
        }
    );
    let centred = constrain_scroll_state(
        &view_200x100(999.0, 0.0, 0.1, Some(scroll_lock.clone())),
        0.0,
    );
    assert!((centred.scroll_x - (200.0 / 0.1 - 1000.0) / 2.0).abs() < 1e-9);

    // "zoom lock (pure)"
    let zoom_lock = ScrollConstraints {
        lock_zoom: true,
        zoom: 0.5,
        ..locked(0.0, 0.0, 1000.0, 1000.0)
    };
    assert_eq!(
        constrain_scroll_state(&view_200x100(0.0, 0.0, 0.1, Some(zoom_lock.clone())), 0.0).zoom,
        0.5
    );
    assert_eq!(
        constrain_scroll_state(
            &view_200x100(0.0, 0.0, MAX_ZOOM, Some(zoom_lock.clone())),
            0.0
        )
        .zoom,
        MAX_ZOOM
    );
    assert_eq!(
        constrain_scroll_state(&view_200x100(0.0, 0.0, 1.5, Some(zoom_lock)), 0.0).zoom,
        1.5
    );

    // "offsets (pure)"
    let with_offsets = ScrollConstraints {
        offsets: Offsets {
            top: 10.0,
            right: 20.0,
            bottom: 30.0,
            left: 40.0,
        },
        ..scroll_lock.clone()
    };
    let r = constrain_scroll_state(
        &view_200x100(999.0, 999.0, 1.0, Some(with_offsets.clone())),
        0.0,
    );
    assert_eq!((r.scroll_x, r.scroll_y), (40.0, 10.0));
    let r = constrain_scroll_state(
        &view_200x100(-5000.0, -5000.0, 1.0, Some(with_offsets)),
        0.0,
    );
    assert_eq!((r.scroll_x, r.scroll_y), (-820.0, -930.0));
    let top_40 = ScrollConstraints {
        offsets: Offsets {
            top: 40.0,
            ..Offsets::default()
        },
        ..scroll_lock.clone()
    };
    assert_eq!(
        constrain_scroll_state(&view_200x100(0.0, 999.0, 2.0, Some(top_40)), 0.0).scroll_y,
        20.0
    );
    let left_40 = ScrollConstraints {
        overscroll: 30.0,
        offsets: Offsets {
            left: 40.0,
            ..Offsets::default()
        },
        ..scroll_lock.clone()
    };
    assert_eq!(
        constrain_scroll_state(&view_200x100(999.0, 0.0, 1.0, Some(left_40)), 30.0).scroll_x,
        70.0
    );

    // "rubberband overscroll (pure)"
    let give = ScrollConstraints {
        overscroll: 30.0,
        ..scroll_lock.clone()
    };
    assert_eq!(
        constrain_scroll_state(&view_200x100(999.0, 0.0, 1.0, Some(give.clone())), 30.0).scroll_x,
        30.0
    );
    assert_eq!(
        constrain_scroll_state(&view_200x100(999.0, 0.0, 2.0, Some(give.clone())), 30.0).scroll_x,
        15.0
    );
    assert_eq!(
        constrain_scroll_state(&view_200x100(999.0, 0.0, 1.0, Some(scroll_lock)), 0.0).scroll_x,
        0.0
    );
    let small = view_200x100(9999.0, 0.0, 0.1, Some(give));
    assert!((constrain_scroll_state(&small, 30.0).scroll_x - 800.0).abs() < 1e-9);
    assert!((constrain_scroll_state(&small, 0.0).scroll_x - 500.0).abs() < 1e-9);
}

fn set_viewport_options(v: &Value) -> SetViewportOptions {
    SetViewportOptions {
        target: v["target"].as_array().map(|_| bounds(&v["target"])),
        fit: match v.get("fit").and_then(Value::as_str) {
            Some("contain") => Fit::Contain,
            Some("none") => Fit::None,
            _ => Fit::ScaleDown,
        },
        offsets: v.get("offsets").map(Offsets::from_json),
        lock: v.get("lock").map(|l| ViewportLock {
            scroll: l["scroll"].as_bool().unwrap_or(false),
            zoom: l["zoom"].as_bool().unwrap_or(false),
            overscroll: match l.get("overscroll") {
                None | Some(Value::Bool(true)) => Overscroll::Default,
                Some(Value::Bool(false)) => Overscroll::Off,
                Some(n) => Overscroll::Give(num(n)),
            },
        }),
        animation: match v.get("animation") {
            None | Some(Value::Bool(true)) => ViewportAnimation::Default,
            Some(Value::Bool(false)) => ViewportAnimation::Off,
            Some(o) => o.get("duration").map_or(ViewportAnimation::Default, |d| {
                ViewportAnimation::Duration(num(d))
            }),
        },
    }
}

#[test]
fn set_viewport_matches_upstream() {
    let f = fixture();
    let cases = f["setViewport"].as_array().expect("setViewport");
    assert!(cases.len() >= 20);
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let mut s = state(&case["state"]);
        let mut cache = case["state"]["shouldCacheIgnoreZoom"].as_bool().unwrap();
        let mut nav = AppViewport::default();
        for (i, step) in case["steps"].as_array().unwrap().iter().enumerate() {
            let what = format!("{name} step {i} {}", step["step"]);
            let kind = step["step"][0].as_str().unwrap();
            let t = num(&step["step"][1]);
            let arg = &step["step"][2];
            let mut calls: Vec<&str> = Vec::new();
            match kind {
                "set" => {
                    if let Some(patch) = nav.set_viewport(&s, &set_viewport_options(arg)) {
                        calls = vec!["requestUnfollow", "cancelSnapBack"];
                        patch.apply(&mut s, &mut cache);
                    }
                }
                "frame" => {
                    if let Some(patch) = nav.frame(t) {
                        patch.apply(&mut s, &mut cache);
                    }
                }
                "translate" => {
                    let update = ViewportUpdate {
                        scroll_x: opt_num(arg, "scrollX"),
                        scroll_y: opt_num(arg, "scrollY"),
                        zoom: opt_num(arg, "zoom"),
                    };
                    let out = nav.translate(&s, Some(update), TranslateOptions::default());
                    assert_eq!(out.is_some(), step["returned"].as_bool().unwrap(), "{what}");
                    if let Some(out) = out {
                        if out.reset_should_cache_ignore_zoom {
                            cache = false;
                        }
                        if out.translation.cancel_snap_back {
                            calls.push("cancelSnapBack");
                        }
                        calls.push("requestUnfollow");
                        s = s.with_viewport(out.translation.viewport);
                    }
                }
                other => panic!("{what}: unknown step {other}"),
            }
            assert_eq!(calls, strings(&step["calls"]), "{what} calls");
            assert_eq!(
                nav.is_locked_transition_pending(),
                step["lockedTransitionPending"].as_bool().unwrap(),
                "{what} lockedTransitionPending"
            );
            assert_eq!(
                nav.is_animating(),
                step["animating"].as_bool().unwrap(),
                "{what} animating"
            );
            let expected = &step["state"];
            assert_viewport(s.viewport(), expected, &what);
            assert_eq!(
                s.scroll_constraints,
                ScrollConstraints::from_json(&expected["scrollConstraints"]),
                "{what} scrollConstraints"
            );
            assert_eq!(
                cache,
                expected["shouldCacheIgnoreZoom"].as_bool().unwrap(),
                "{what} shouldCacheIgnoreZoom"
            );
        }
    }
}

#[test]
fn set_viewport_eases_out_over_the_duration() {
    // easeOut (packages/common/src/utils.ts:232-234): 1 - (1 - k)^4
    assert_eq!(ease_out(0.0), 0.0);
    assert_eq!(ease_out(0.5), 0.9375);
    assert_eq!(ease_out(1.0), 1.0);
    // the search menu's navigation: 300 ms, settled on the last frame
    let s = ViewportState {
        width: 1000.0,
        height: 800.0,
        ..state(&json!({ "zoom": 1 }))
    };
    let mut nav = AppViewport::default();
    let opts = SetViewportOptions {
        animation: ViewportAnimation::Duration(300.0),
        ..SetViewportOptions::new([2000.0, 1500.0, 2100.0, 1540.0])
    };
    let first = nav.set_viewport(&s, &opts).expect("resolved");
    assert_eq!(first.should_cache_ignore_zoom, Some(true));
    assert!(nav.is_animating());
    assert!(nav.frame(10.0).is_some());
    let mid = nav.frame(160.0).expect("a frame");
    assert_eq!(mid.should_cache_ignore_zoom, Some(true));
    assert!(nav.is_animating());
    let last = nav.frame(310.0).expect("the last frame");
    assert_eq!(last.should_cache_ignore_zoom, Some(false));
    assert_eq!(last.scroll_constraints, Some(None));
    assert!(!nav.is_animating());
    assert_eq!(nav.frame(400.0), None);
}

