// -- zoom to fit, scrolling to bounds ------------------------------------------------

fn fit_options(bounds: [f64; 4], offsets: Offsets, o: &Value) -> ZoomToFit {
    ZoomToFit {
        bounds,
        canvas_offsets: offsets,
        fit: match o.get("fit").and_then(Value::as_str) {
            None | Some("scale-down") => Fit::ScaleDown,
            Some("contain") => Fit::Contain,
            Some("none") => Fit::None,
            Some(other) => panic!("fit {other}"),
        },
        min_zoom: opt_num(o, "minZoom").unwrap_or(f64::NEG_INFINITY),
        max_zoom: opt_num(o, "maxZoom").unwrap_or(f64::INFINITY),
        stepped_zoom: o
            .get("steppedZoom")
            .and_then(Value::as_bool)
            .unwrap_or(false),
    }
}

