#[test]
fn scroll_bounds_into_view_upstream_cases() {
    // tests/viewport.test.ts
    let s = |zoom: f64| ViewportState {
        scroll_x: 0.0,
        scroll_y: 0.0,
        zoom,
        width: 1000.0,
        height: 800.0,
        offset_left: 0.0,
        offset_top: 0.0,
        scroll_constraints: None,
    };
    let none = Offsets::default();
    let right = |r: f64| Offsets {
        right: r,
        ..Offsets::default()
    };
    let go = |b: [f64; 4], st: &ViewportState, o: &Offsets, t: TooLarge| {
        scroll_bounds_into_view(b, st, o, t)
    };
    assert_eq!(
        go(
            [100.0, 100.0, 200.0, 200.0],
            &s(1.0),
            &none,
            TooLarge::AlignStart
        ),
        None
    );
    assert_eq!(
        go(
            [900.0, -30.0, 1050.0, 100.0],
            &s(1.0),
            &none,
            TooLarge::AlignStart
        ),
        Some((-50.0, 30.0))
    );
    assert_eq!(
        go(
            [900.0, 100.0, 1000.0, 200.0],
            &s(1.0),
            &right(320.0),
            TooLarge::AlignStart
        ),
        Some((-320.0, 0.0))
    );
    assert_eq!(
        go(
            [450.0, 100.0, 550.0, 150.0],
            &s(2.0),
            &none,
            TooLarge::AlignStart
        ),
        Some((-50.0, 0.0))
    );
    assert_eq!(
        go(
            [100.0, 500.0, 200.0, 2000.0],
            &s(1.0),
            &none,
            TooLarge::AlignStart
        ),
        Some((0.0, -500.0))
    );
    assert_eq!(
        go(
            [100.0, 500.0, 200.0, 2000.0],
            &s(1.0),
            &none,
            TooLarge::Leave
        ),
        None
    );
    let both = Offsets {
        left: 600.0,
        right: 600.0,
        ..Offsets::default()
    };
    assert_eq!(
        go(
            [900.0, 0.0, 1100.0, 10.0],
            &s(1.0),
            &both,
            TooLarge::AlignStart
        ),
        None
    );
}

