// -- the wheel ---------------------------------------------------------------------------

fn wheel_event(e: &Value) -> WheelEvent {
    let flag = |k: &str| e.get(k).and_then(Value::as_bool).unwrap_or(false);
    WheelEvent {
        delta_x: opt_num(e, "deltaX").unwrap_or(0.0),
        delta_y: opt_num(e, "deltaY").unwrap_or(0.0),
        ctrl_key: flag("ctrlKey"),
        meta_key: flag("metaKey"),
        shift_key: flag("shiftKey"),
        buttons: e.get("buttons").and_then(Value::as_u64).unwrap_or(0) as u16,
        target: match e.get("target").and_then(Value::as_str).unwrap_or("canvas") {
            "canvas" => WheelTarget::Canvas,
            "textarea" => WheelTarget::TextArea,
            "iframe" => WheelTarget::IFrame,
            "frameName" => WheelTarget::FrameName,
            "other" => WheelTarget::Other,
            other => panic!("target {other}"),
        },
    }
}

fn outcome_calls(o: &WheelOutcome) -> Vec<&'static str> {
    let mut calls = Vec::new();
    if o.flush_pan_move {
        calls.push("flushMove");
    }
    if let Some(t) = &o.translation {
        calls.extend(translation_calls(t));
    }
    if o.reset_should_cache_ignore_zoom {
        calls.push("resetShouldCacheIgnoreZoom");
    }
    calls
}

#[test]
fn wheel_matches_upstream_event_by_event() {
    let f = fixture();
    let wheel = &f["wheel"];
    // the fixture ran with navigator.platform "" (not a Mac): CTRL_OR_CMD
    // is ctrlKey
    let is_darwin = wheel["ctrlOrCmd"] == "metaKey";
    let sequences = wheel["sequences"].as_array().expect("sequences");
    assert!(sequences.len() >= 200);
    for seq in sequences {
        let name = seq["name"].as_str().unwrap();
        let mut s = state(&seq["state"]);
        let mut should_cache_ignore_zoom = false;
        let ctx = WheelContext {
            navigation_enabled: seq["navigation"].as_bool().unwrap(),
            pan_active: seq["panActive"].as_bool().unwrap(),
            input_device: InputDevice::from_name(seq["state"]["inputDevice"].as_str().unwrap())
                .unwrap(),
            last_position: (
                num(&seq["lastPosition"]["x"]),
                num(&seq["lastPosition"]["y"]),
            ),
            is_darwin,
        };
        for (i, step) in seq["steps"].as_array().unwrap().iter().enumerate() {
            let what = format!("{name} step {i} {}", step["event"]);
            let o = handle_wheel(&s, &ctx, &wheel_event(&step["event"]));
            assert_eq!(
                o.prevent_default,
                step["prevented"].as_bool().unwrap(),
                "{what} prevented"
            );
            assert_eq!(outcome_calls(&o), strings(&step["calls"]), "{what} calls");
            if let Some(t) = &o.translation {
                s = s.with_viewport(t.viewport);
            }
            should_cache_ignore_zoom |= o.should_cache_ignore_zoom;
            assert_viewport(s.viewport(), &step["state"], &what);
            assert_eq!(
                should_cache_ignore_zoom,
                step["state"]["shouldCacheIgnoreZoom"].as_bool().unwrap(),
                "{what}"
            );
        }
    }
}

fn editor(zoom: f64, input_device: InputDevice) -> (ViewportState, WheelContext) {
    (
        ViewportState {
            scroll_x: 0.0,
            scroll_y: 0.0,
            zoom,
            width: 1000.0,
            height: 800.0,
            offset_left: 0.0,
            offset_top: 0.0,
            scroll_constraints: None,
        },
        WheelContext {
            navigation_enabled: true,
            pan_active: false,
            input_device,
            last_position: (100.0, 100.0),
            is_darwin: false,
        },
    )
}

fn ev(delta_x: f64, delta_y: f64) -> WheelEvent {
    WheelEvent {
        delta_x,
        delta_y,
        ..WheelEvent::default()
    }
}

fn apply(s: &ViewportState, o: &WheelOutcome) -> ViewportState {
    o.translation
        .as_ref()
        .map_or_else(|| s.clone(), |t| s.with_viewport(t.viewport))
}

#[test]
fn upstream_wheel_suite() {
    // wheel.test.tsx "pans on plain wheel, horizontally with shift, and
    // zooms on ctrl/cmd+wheel"
    let (s, ctx) = editor(1.0, InputDevice::Auto);
    let s = apply(&s, &handle_wheel(&s, &ctx, &ev(30.0, 40.0)));
    assert_eq!(
        s.viewport(),
        Viewport {
            scroll_x: -30.0,
            scroll_y: -40.0,
            zoom: 1.0
        }
    );
    let s = apply(
        &s,
        &handle_wheel(
            &s,
            &ctx,
            &WheelEvent {
                shift_key: true,
                ..ev(0.0, 40.0)
            },
        ),
    );
    assert_eq!(
        s.viewport(),
        Viewport {
            scroll_x: -70.0,
            scroll_y: -40.0,
            zoom: 1.0
        }
    );
    let zoomed = apply(
        &s,
        &handle_wheel(
            &s,
            &ctx,
            &WheelEvent {
                ctrl_key: true,
                ..ev(0.0, -100.0)
            },
        ),
    );
    assert!(zoomed.zoom > 1.0);
    let out = apply(
        &zoomed,
        &handle_wheel(
            &zoomed,
            &ctx,
            &WheelEvent {
                meta_key: true,
                ..ev(0.0, 100.0)
            },
        ),
    );
    assert!(out.zoom < zoomed.zoom);

    // "does nothing on a zoom tick at the zoom limit"
    let (s, ctx) = editor(MIN_ZOOM, InputDevice::Auto);
    let o = handle_wheel(
        &s,
        &ctx,
        &WheelEvent {
            ctrl_key: true,
            ..ev(0.0, 100.0)
        },
    );
    assert_eq!(apply(&s, &o).viewport(), s.viewport());
    assert!(!o.should_cache_ignore_zoom);

    // "wheel button held down: zooms instead of panning, whatever the modifiers"
    let (s, ctx) = editor(1.0, InputDevice::Auto);
    let held = |dy: f64, shift: bool| WheelEvent {
        buttons: 4,
        shift_key: shift,
        ..ev(0.0, dy)
    };
    let a = apply(&s, &handle_wheel(&s, &ctx, &held(-100.0, false)));
    assert!(a.zoom > 1.0);
    let b = apply(&a, &handle_wheel(&a, &ctx, &held(100.0, false)));
    assert!(b.zoom < a.zoom);
    let c = apply(&b, &handle_wheel(&b, &ctx, &held(-100.0, true)));
    assert!(c.zoom > b.zoom);

    // "zooms during the wheel-button drag-pan the button started"
    let (s, mut ctx) = editor(1.0, InputDevice::Auto);
    ctx.pan_active = true;
    let o = handle_wheel(&s, &ctx, &ev(0.0, 40.0));
    assert!(o.translation.is_none() && !o.flush_pan_move);
    let o = handle_wheel(&s, &ctx, &held(-100.0, false));
    assert!(o.flush_pan_move);
    assert!(apply(&s, &o).zoom > 1.0);
    ctx.pan_active = false;
    let released = apply(&s, &o);
    let after = apply(&released, &handle_wheel(&released, &ctx, &ev(0.0, 40.0)));
    assert!((after.scroll_y - (released.scroll_y - 40.0 / released.zoom)).abs() < 1e-9);
}

#[test]
fn upstream_input_device_suite() {
    // "defaults to auto, which resolves to trackpad until detection exists"
    let app_state = AppState::default();
    assert_eq!(InputDevice::from_app_state(&app_state), InputDevice::Auto);
    assert_eq!(InputDevice::Auto.resolve(), InputDevice::Trackpad);

    // "shift+wheel with %s input": pans only the named axis
    for device in [InputDevice::Auto, InputDevice::Mouse, InputDevice::Trackpad] {
        for (ctrl, meta, vertical) in [
            (false, false, false),
            (true, false, true),
            (false, true, true),
        ] {
            let (mut s, ctx) = editor(2.0, device);
            s.scroll_x = 12.0;
            s.scroll_y = 34.0;
            let e = WheelEvent {
                shift_key: true,
                ctrl_key: ctrl,
                meta_key: meta,
                ..ev(10.0, 40.0)
            };
            let moved = apply(&s, &handle_wheel(&s, &ctx, &e));
            let want = if vertical { (12.0, 14.0) } else { (-8.0, 34.0) };
            assert_eq!(
                (moved.scroll_x, moved.scroll_y, moved.zoom),
                (want.0, want.1, 2.0),
                "{device:?}"
            );
            let e = WheelEvent {
                shift_key: true,
                ctrl_key: ctrl,
                meta_key: meta,
                ..ev(-40.0, 0.0)
            };
            let back = apply(&moved, &handle_wheel(&moved, &ctx, &e));
            assert_eq!(back.viewport(), s.viewport(), "{device:?}");
        }
    }

    // "mouse": zooms around the pointer on plain, ctrl and cmd wheel
    for (ctrl, meta) in [(false, false), (true, false), (false, true)] {
        let (s, ctx) = editor(1.0, InputDevice::Mouse);
        let before = viewport_coords_to_scene_coords(100.0, 100.0, &s);
        let e = |dy: f64| WheelEvent {
            ctrl_key: ctrl,
            meta_key: meta,
            ..ev(0.0, dy)
        };
        let zoomed = apply(&s, &handle_wheel(&s, &ctx, &e(-100.0)));
        assert!(zoomed.zoom > 1.0);
        let p = viewport_coords_to_scene_coords(100.0, 100.0, &zoomed);
        assert!((p.0 - before.0).abs() < 1e-9 && (p.1 - before.1).abs() < 1e-9);
        let out = apply(&zoomed, &handle_wheel(&zoomed, &ctx, &e(100.0)));
        assert!(out.zoom < zoomed.zoom);
        let p = viewport_coords_to_scene_coords(100.0, 100.0, &out);
        assert!((p.0 - before.0).abs() < 1e-9 && (p.1 - before.1).abs() < 1e-9);
    }
    // "keeps zooming with the wheel button held"
    let (s, ctx) = editor(1.0, InputDevice::Mouse);
    let e = WheelEvent {
        buttons: 4,
        ctrl_key: true,
        shift_key: true,
        ..ev(0.0, -100.0)
    };
    assert!(apply(&s, &handle_wheel(&s, &ctx, &e)).zoom > 1.0);
    // "pans sideways on a horizontal-only wheel instead of zooming"
    let o = handle_wheel(&s, &ctx, &ev(30.0, 0.0));
    assert_eq!(
        apply(&s, &o).viewport(),
        Viewport {
            scroll_x: -30.0,
            scroll_y: 0.0,
            zoom: 1.0
        }
    );
    assert!(!o.should_cache_ignore_zoom);
}

#[test]
fn wheel_outside_the_editor_surfaces() {
    let (s, ctx) = editor(1.0, InputDevice::Auto);
    // menus and sidebars keep scrolling; only the browser zoom is prevented
    let o = handle_wheel(
        &s,
        &ctx,
        &WheelEvent {
            target: WheelTarget::Other,
            ..ev(0.0, 40.0)
        },
    );
    assert!(!o.prevent_default && o.translation.is_none());
    let o = handle_wheel(
        &s,
        &ctx,
        &WheelEvent {
            target: WheelTarget::Other,
            ctrl_key: true,
            ..ev(0.0, 40.0)
        },
    );
    assert!(o.prevent_default && o.translation.is_none());
    // CTRL_OR_CMD is metaKey on a Mac
    let mac = WheelContext {
        is_darwin: true,
        ..ctx
    };
    let o = handle_wheel(
        &s,
        &mac,
        &WheelEvent {
            target: WheelTarget::Other,
            meta_key: true,
            ..ev(0.0, 40.0)
        },
    );
    assert!(o.prevent_default && o.translation.is_none());
    let o = handle_wheel(
        &s,
        &mac,
        &WheelEvent {
            target: WheelTarget::Other,
            ctrl_key: true,
            ..ev(0.0, 40.0)
        },
    );
    assert!(!o.prevent_default);
    // frame labels are editor surface: "wheel over a frame label is handled once"
    let o = handle_wheel(
        &s,
        &ctx,
        &WheelEvent {
            target: WheelTarget::FrameName,
            ..ev(0.0, 40.0)
        },
    );
    assert_eq!(apply(&s, &o).scroll_y, -40.0);
    // navigation disabled: nothing at all
    let off = WheelContext {
        navigation_enabled: false,
        ..ctx
    };
    let o = handle_wheel(
        &s,
        &off,
        &WheelEvent {
            ctrl_key: true,
            ..ev(0.0, 40.0)
        },
    );
    assert!(!o.prevent_default && o.translation.is_none());
}

